} else {
    var MockJs = require('mockjs');
    let userName = 'admin'
    if(token.startsWith('test')){
        userName = 'test'
    } else if(token.startsWith('superAdmin')){
        userName = 'superAdmin'
    } else if(token.startsWith('superadmin')){
        userName = 'superadmin'
    }
    responseJson.data.token = MockJs.mock("@pick(['test'])")+MockJs.mock("@id")+'isPlay'+userName
}
fox.mockResponse.setBody(responseJson);

